"""Prepare immutable old production sources for regression and same-machine A/B."""
from pathlib import Path
import hashlib
import subprocess
from prepare_bridge import COMMIT, ROOT
from generate_ipc_baseline_test import BASE_PATCH_SHA

BASE = 'cf49175e8a3c6c2fe45c99aec0680b0d1c864d24'


def prepare():
    source = ROOT / '.deps/dxvk-remix'
    baseline = ROOT / '.deps/ipc-v1.2.1'
    patch = subprocess.check_output(['git','show',BASE+':patches/l4d2-bridge.patch'],cwd=ROOT)
    if hashlib.sha256(patch).hexdigest() != BASE_PATCH_SHA:
        raise RuntimeError('Baseline patch hash mismatch')
    if not baseline.exists():
        subprocess.run(['git','worktree','add','--detach',str(baseline),COMMIT],cwd=source,check=True)
        subprocess.run(['git','apply','--check','-'],input=patch,cwd=baseline,check=True)
        subprocess.run(['git','apply','-'],input=patch,cwd=baseline,check=True)
    else:
        subprocess.run(['git','apply','--reverse','--check','-'],input=patch,cwd=baseline,check=True)
    return baseline


if __name__ == '__main__':
    print(prepare())
